from pathlib import Path
import sys

ROOT=Path(__file__).resolve().parents[2]
checks=[]
def text(path): return (ROOT/path).read_text(encoding='utf-8')
def check(label,cond):
    checks.append((label,bool(cond)))
    print(('PASS' if cond else 'FAIL')+' - '+label)

service=text(Path('src/main/java/com/example/editor/transformation/export/TransformationExportService.java'))
registry=text(Path('src/main/java/com/example/editor/transformation/export/TransformationLanguageAdapterRegistry.java'))
canonical=text(Path('src/main/java/com/example/editor/transformation/export/CanonicalRuntimeBundleSupport.java'))
declarative=text(Path('src/main/java/com/example/editor/transformation/export/DeclarativeM2MExportSupport.java'))
templates=text(Path('src/main/java/com/example/editor/transformation/export/TemplateM2TExportSupport.java'))
atl=text(Path('src/main/java/com/example/editor/transformation/export/AtlTransformationLanguageAdapter.java'))
etl=text(Path('src/main/java/com/example/editor/transformation/export/EtlTransformationLanguageAdapter.java'))
acceleo=text(Path('src/main/java/com/example/editor/transformation/export/AcceleoTransformationLanguageAdapter.java'))
egl=text(Path('src/main/java/com/example/editor/transformation/export/EglTransformationLanguageAdapter.java'))
controller=text(Path('src/main/java/com/example/editor/transformation/web/TransformationController.java'))
designer=text(Path('frontend/src/transformation-designer/TransformationDesigner.tsx'))
bindings=text(Path('frontend/src/transformation-designer/TransformationBindingRow.tsx'))
relations=text(Path('frontend/src/transformation-designer/TransformationRelationBindings.tsx'))
generation=text(Path('frontend/src/transformation-designer/TransformationGenerationWorkspace.tsx'))
t2m=text(Path('frontend/src/transformation-designer/TransformationTextToModelWorkspace.tsx'))
preview=text(Path('frontend/src/transformation-designer/TransformationPreviewPanel.tsx'))
export_panel=text(Path('frontend/src/transformation-designer/TransformationExportPanel.tsx'))
api=text(Path('frontend/src/transformation-designer/api.ts'))
types=text(Path('frontend/src/transformation-designer/types.ts'))
model=text(Path('frontend/src/transformation-designer/transformationDesignerModel.ts'))
contract=text(Path('frontend/src/transformation-designer/TransformationDesignerContract.test.ts'))
css=text(Path('frontend/src/transformation-designer/transformation-designer.css'))
doc=text(Path('docs/architecture/transformation-layer.md'))

check('export service checks canonical definition before adapter execution','checker.check' in service and 'report.valid()' in service)
check('export endpoint resolution follows transformation kind','document.kind() == TransformationKind.T2M ? null' in service and 'document.kind() == TransformationKind.M2M' in service and 'canonicalSource' in service and 'canonicalTarget' in service)
check('adapter registry rejects duplicate technologies','putIfAbsent' in registry and 'Duplicate transformation adapter' in registry)
check('canonical Java/Xtend bundles retain complete definition','transformation.json' in canonical and 'CANONICAL_RUNTIME' in canonical)
check('canonical runtime bundles cover M2M M2T T2M','Set.of(TransformationKind.M2M,TransformationKind.M2T,TransformationKind.T2M)' in canonical)
check('ATL and ETL subset blocks guards','GUARD_NOT_NATIVE' in declarative)
check('ATL and ETL subset blocks unprojected value policies','VALUE_POLICY_NOT_NATIVE' in declarative)
check('ATL and ETL direct copies require exact type and multiplicity','DIRECT_BINDING_NOT_EXACT' in declarative)
check('ATL adapter emits native ATL artifact','.atl' in atl and 'create OUT : TARGET from IN : SOURCE' in atl)
check('ETL adapter emits native ETL artifact','.etl' in etl and 'transform ' in etl)
check('template adapters block canonical identity tokens','CANONICAL_ID_TOKEN_NOT_NATIVE' in templates)
check('template adapters block untranslated guards','GUARD_NOT_NATIVE' in templates)
check('Acceleo adapter emits MTL','.mtl' in acceleo and '[template public ' in acceleo)
check('EGL adapter emits template and EGX orchestration','.egl' in egl and '.egx' in egl)
check('controller exposes language catalogue and draft export','/export-languages' in controller and '@PostMapping("/export")' in controller)
check('frontend API exposes compatibility-aware export','listTransformationExportLanguages' in api and 'exportTransformation' in api)
check('frontend export contract names all implemented adapters',all(token in types for token in ["'ATL'","'ETL'","'JAVA'","'XTEND'","'ACCELEO'","'EGL'"]))
check('guided and manual editing still share one canonical document','useState<TransformationDefinitionDocument>' in designer and 'guidedDocument' not in designer and 'advancedDocument' not in designer)
check('designer dispatches authoring by M2M M2T T2M kind',"document.kind === 'M2M'" in designer and "document.kind === 'M2T'" in designer and 'TransformationTextToModelWorkspace' in designer)
check('M2M property authoring exposes direct constant and expression sources',all(token in bindings for token in ["value:'DIRECT'","value:'CONSTANT'","value:'EXPRESSION'"]))
check('M2M value adaptation exposes collection conversion and error policies','Collection adaptation' in bindings and 'Type conversion' in bindings and 'On mapping error' in bindings)
check('M2M relation authoring uses trace-equivalent mappings','TRACE_EQUIVALENT' in relations)
check('M2T authoring exposes context path template collision and guard','createGenerationRule' in generation and 'Output path template' in generation and 'Artifact collision' in generation and 'GuidedConditionBuilder' in generation)
check('T2M authoring exposes grammar path and optional M2M projection','grammarId' in t2m and 'relativePath' in t2m and 'postTransformationId' in t2m)
check('preview panel executes all three families side-effect free','previewTransformation' in preview and 'previewModelToText' in preview and 'previewTextToModel' in preview)
check('export panel surfaces compatibility fidelity diagnostics and files','result.compatible' in export_panel and 'result.fidelity' in export_panel and 'result.diagnostics' in export_panel and 'result.artifacts' in export_panel)
check('designer model switches family without changing document identity','withTransformationKind' in model and '...document, kind' in model)
check('frontend contract tests cover M2T T2M preview and export','authors M2T and T2M' in contract and 'compatibility-aware adapters' in contract)
check('backend adapter tests cover exact bundle fail-closed ATL and Acceleo',(ROOT/'src/test/java/com/example/editor/transformation/export/TransformationLanguageAdapterTests.java').exists())
check('CSS remains within shared giant-line ceiling',max((len(line) for line in css.splitlines()),default=0)<=1400)
check('architecture document still declares neutral canonical source of truth','modelo canónico de HYDRA' in doc and 'ningún lenguaje externo' in doc)

passed=sum(ok for _,ok in checks)
print(f'TRANSFORMATION_LAYER_FIX19={passed}/{len(checks)} '+('PASS' if passed==len(checks) else 'FAIL'))
sys.exit(0 if passed==len(checks) else 1)
